"""Recompute evidence-weighted audit scores. No network or database access."""
import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
rows = []

def add(id, module, requirement, weight, source, runtime, approval, tags, evidence, gap, close, dependency):
    # runtime=None means this criterion is a local/source criterion, not a live claim.
    # approval=None means no independent approval is required for this narrow criterion.
    q = min([source] + ([runtime] if runtime is not None else []) + ([approval] if approval is not None else []))
    achieved = 'RUNTIME_VERIFIED' if runtime == 1 else 'IMPLEMENTED' if source == 1 else 'SOURCE_PRESENT' if source else 'NOT_STARTED'
    rows.append(dict(id=id,module=module,requirement=requirement,weight=weight,
        weight_reason={5:'عزل/صلاحيات/سلامة بيانات أو مانع إطلاق',3:'وظيفة أساسية أو اعتماد تشغيلي',2:'تجربة/اكتشاف/تشغيل مساند',1:'تحسين مساعد'}[weight],
        source=source,runtime=runtime,approval=approval,readiness=q,
        status='BLOCKED' if (runtime == 0 or approval == 0) else achieved,achieved_level=achieved,
        tags=tags.split(),evidence=evidence,gap=gap,closure=close,dependency=dependency,
        earned=weight*(source+(runtime or 0)+(approval or 0)),possible=weight*(1+(runtime is not None)+(approval is not None))))

# S=1: criterion verified now; .5: implementation inspected, acceptance unproven;
# .25: source/document present, executable path missing or not reviewed; 0: no evidence.
