# Editorial overrides preserve scoring and make Arabic acceptance criteria readable.
overrides = json.loads((ROOT/'readability-overrides.json').read_text())
for row in rows:
    row['gap'], row['closure'] = overrides[row['id']]

def metric(items, key):
    valid=[r for r in items if r[key] is not None]
    return dict(earned=round(sum(r['weight']*r[key] for r in valid),2),possible=sum(r['weight'] for r in valid),
                percent=round(100*sum(r['weight']*r[key] for r in valid)/sum(r['weight'] for r in valid),2) if valid else None)
scores={'Source Implementation Completion':metric(rows,'source'),'Runtime Verification Completion':metric(rows,'runtime')}
for tag,name in [('security','Security & Compliance Readiness'),('product','Product Functional Readiness'),('ui','UI/UX Completion'),('seo','SEO Readiness'),('beta','Beta Launch Readiness'),('commercial','Commercial Production Readiness')]:
    scores[name]=metric([r for r in rows if tag in r['tags']],'readiness')
earned=sum(r['earned'] for r in rows);possible=sum(r['possible'] for r in rows)
scores['Overall staged evidence completion']={'earned':round(earned,2),'possible':possible,'percent':round(100*earned/possible,2)}
modules={m:{'source':metric([r for r in rows if r['module']==m],'source'),'runtime':metric([r for r in rows if r['module']==m],'runtime'),'readiness':metric([r for r in rows if r['module']==m],'readiness')} for m in dict.fromkeys(r['module'] for r in rows)}
(ROOT/'requirements.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(ROOT/'scores.json').write_text(json.dumps({'scores':scores,'modules':modules,'requirements':len(rows)},ensure_ascii=False,indent=2)+'\n')
with (ROOT/'requirements.csv').open('w',newline='') as f:
    writer=csv.DictWriter(f,fieldnames=rows[0].keys());writer.writeheader();writer.writerows(rows)
md=['# مصفوفة المتطلبات والأدلة','',f'عدد المتطلبات: {len(rows)}. الأوزان: 5 أمان/سلامة/إطلاق، 3 وظيفة أو اعتماد، 2 تجربة/اكتشاف. NOT_VERIFIED يمنح صفر تشغيل، ولا يعني أن الوظيفة مستحيلة.','',
    'S: 1 تحقق المعيار المحدد حاليًا؛ 0.5 تنفيذ قُرئ ولم يثبت قبولُه؛ 0.25 ملفات/وثيقة دون مسار مكتمل؛ 0 غياب دليل. R: تشغيل فعلي للمعيار نفسه (1/0)، — غير منطبق. A: اعتماد مستقل مثبت (1/0)، — غير مطلوب لهذا المعيار. حالة BLOCKED تحتفظ بمستوى المصدر في achieved_level.','',
    'النقاط الكلية لكل صف = weight × (S + R المنطبق + A المنطبق). المقام = weight × عدد المراحل المنطبقة. الجاهزية Q = أصغر قيمة للمراحل المنطبقة؛ لا تعوّض نقاط المصدر فشل التشغيل/الموافقة. هذه مصفوفة تدقيق أولية وليست عقد متطلبات موقعًا ولا نسبة كل كود ممكن.','',
    '| ID | الوحدة والمعيار | W | S | R | A | المكتسب/الممكن | الحالة/المستوى |','|---|---|---:|---:|---:|---:|---:|---|']
for r in rows:
    md.append(f"| {r['id']} | {r['module']}: {r['requirement']} | {r['weight']} | {r['source']} | {r['runtime'] if r['runtime'] is not None else '—'} | {r['approval'] if r['approval'] is not None else '—'} | {r['earned']}/{r['possible']} | {r['status']} / {r['achieved_level']} |")
for r in rows:
    md += ['',f"## {r['id']} — {r['requirement']}",f"- الدليل: `{r['evidence']}`.",f"- سبب النقاط/النقص: {r['gap']}.",f"- الاعتماديات: {r['dependency']}.",f"- معيار الإغلاق: {r['closure']}."]
(ROOT/'REQUIREMENTS.md').write_text('\n'.join(md)+'\n')
print(json.dumps({'count':len(rows),'scores':scores,'modules':modules},ensure_ascii=False,indent=2))
